  const MEMBER_MANAGEMENT_STORAGE_KEY = "rw_payout_helper_member_management_state";
  const MEMBER_MANAGEMENT_EXPIRY_MS = 20 * 60 * 1000;

  const RWPH_PAYMENTS_ONLY_SESSION_KEY = "rwph_payments_only_tab";

  function rwphIsPaymentsOnlyTabUrl() {
    try {
      const href = String(window.location.href || "");
      return href.includes("/factions.php") && href.includes("rwphPayAll=1");
    } catch (_) {
      return false;
    }
  }

  function rwphMarkPaymentsOnlyTab() {
    try {
      if (rwphIsPaymentsOnlyTabUrl()) sessionStorage.setItem(RWPH_PAYMENTS_ONLY_SESSION_KEY, "1");
    } catch (_) {}
  }

  function rwphIsPaymentsOnlyTabContext() {
    try {
      return rwphIsPaymentsOnlyTabUrl() || sessionStorage.getItem(RWPH_PAYMENTS_ONLY_SESSION_KEY) === "1";
    } catch (_) {
      return rwphIsPaymentsOnlyTabUrl();
    }
  }

  function rwphInstallPaymentsOnlyPanelGuard() {
    if (!rwphIsPaymentsOnlyTabContext()) return;
    rwphMarkPaymentsOnlyTab();
    try { rwphSetPaymentsOnlyTabRestoreState(); } catch (_) {}

    try {
      if (!document.getElementById("rwph-payments-only-panel-guard-style")) {
        const style = document.createElement("style");
        style.id = "rwph-payments-only-panel-guard-style";
        style.textContent = `
          #rw-payout-helper,
          #rw-results-panel,
          #rwph-results-loading-panel,
          .rwph-results-loading-panel,
          .rw-results-panel,
          #rwph-export-html-panel {
            display:none!important;
            visibility:hidden!important;
            opacity:0!important;
            pointer-events:none!important;
          }
          #rw-pay-all-panel,
          .rw-pay-all-panel {
            display:flex!important;
            visibility:visible!important;
            opacity:1!important;
            pointer-events:auto!important;
          }
        `;
        (document.head || document.documentElement).appendChild(style);
      }
    } catch (_) {}

    const removeWrongPanels = () => {
      try {
        const selectors = [
          "#rw-payout-helper",
          "#rw-results-panel",
          "#rwph-results-loading-panel",
          ".rwph-results-loading-panel",
          ".rw-results-panel",
          "#rwph-export-html-panel"
        ].join(",");
        document.querySelectorAll(selectors).forEach((el) => {
          if (!el || el.id === "rw-pay-all-panel" || el.classList?.contains("rw-pay-all-panel")) return;
          try { el.remove(); } catch (_) {}
        });
      } catch (_) {}
    };

    removeWrongPanels();
    try {
      if (!window.rwphPaymentsOnlyPanelGuardObserver) {
        window.rwphPaymentsOnlyPanelGuardObserver = new MutationObserver(removeWrongPanels);
        window.rwphPaymentsOnlyPanelGuardObserver.observe(document.documentElement || document.body, { childList: true, subtree: true });
      }
    } catch (_) {}
    [50, 150, 300, 650, 1200, 2500].forEach((ms) => setTimeout(removeWrongPanels, ms));
  }

  function rwphRememberOpenResultsPageHtml(html) {
    try {
      const value = String(html || "");
      if (!value || value.length < 1000) return;
      localStorage.setItem(LAST_RESULTS_HTML_OPEN_STORAGE_KEY, JSON.stringify({
        active: true,
        url: String(location.href || ""),
        createdAt: Date.now(),
        html: value
      }));
    } catch (e) {
      console.warn("RWPH could not remember open results page:", e);
    }
  }

  function rwphClearRememberedOpenResultsPage() {
    try { localStorage.removeItem(LAST_RESULTS_HTML_OPEN_STORAGE_KEY); } catch (_) {}
  }

  function rwphCurrentTopPageUrl() {
    try {
      if (window.top && window.top.location && window.top.location.href && String(window.top.location.href) !== "about:blank") {
        return String(window.top.location.href);
      }
    } catch (_) {}
    try {
      if (window.parent && window.parent.location && window.parent.location.href && String(window.parent.location.href) !== "about:blank") {
        return String(window.parent.location.href);
      }
    } catch (_) {}
    return String(location.href || "");
  }

  function rwphRememberResultsLoadingPanelState(state = {}) {
    try {
      const progressId = String(state.progressId || "").trim();
      const html = String(state.html || "");
      if (!progressId && !html) return;
      const current = rwphReadResultsLoadingPanelState(false) || {};
      localStorage.setItem(RESULTS_LOADING_PANEL_STATE_STORAGE_KEY, JSON.stringify({
        ...current,
        ...state,
        active: true,
        url: rwphCurrentTopPageUrl(),
        createdAt: Date.now(),
        updatedAt: Date.now(),
        progressId,
        startedAtMs: Number(state.startedAtMs || current.startedAtMs || Date.now()),
        type: String(state.type || current.type || (html ? "ready" : "loading")),
      }));
    } catch (e) {
      console.warn("RWPH could not remember results loading panel state:", e);
    }
  }

  function rwphReadResultsLoadingPanelState(validateAge = true) {
    try {
      const raw = localStorage.getItem(RESULTS_LOADING_PANEL_STATE_STORAGE_KEY);
      if (!raw) return null;
      const stored = JSON.parse(raw);
      if (!stored || !stored.active) return null;
      const age = Date.now() - Number(stored.createdAt || stored.updatedAt || 0);
      if (validateAge && (!isFinite(age) || age < 0 || age > 24 * 60 * 60 * 1000)) {
        localStorage.removeItem(RESULTS_LOADING_PANEL_STATE_STORAGE_KEY);
        return null;
      }
      return stored;
    } catch (_) {
      return null;
    }
  }

  function rwphClearResultsLoadingPanelState() {
    try { localStorage.removeItem(RESULTS_LOADING_PANEL_STATE_STORAGE_KEY); } catch (_) {}
  }

  function rwphRestoreOpenResultsPageAfterRefresh() {
    // v1.1.534: migrate the retired standalone-results restore record into the
    // proper Results panel state. Never replace the Torn document with Results.
    try {
      if (rwphIsPaymentsOnlyTabContext()) return false;
      const raw = localStorage.getItem(LAST_RESULTS_HTML_OPEN_STORAGE_KEY);
      if (!raw) return false;
      const stored = JSON.parse(raw);
      rwphClearRememberedOpenResultsPage();
      if (!stored || !stored.active || !stored.html) return false;
      const age = Date.now() - Number(stored.createdAt || 0);
      if (!isFinite(age) || age < 0 || age > 24 * 60 * 60 * 1000) return false;
      const html = String(stored.html || "");
      if (!/<html[\s>]/i.test(html) && !/<!doctype html/i.test(html)) return false;
      const existing = rwphReadResultsLoadingPanelState(false);
      if (!existing?.active) {
        localStorage.setItem(RESULTS_LOADING_PANEL_STATE_STORAGE_KEY, JSON.stringify({
          active: true, type: "results", progressId: "", html,
          url: rwphCurrentTopPageUrl(), createdAt: Date.now(), updatedAt: Date.now(),
          startedAtMs: Number(stored.createdAt || Date.now()),
        }));
      }
    } catch (e) {
      console.warn("RWPH legacy results restore migration failed:", e);
    }
    return false;
  }

