  async function rwphOpenDefaultSetupActualPanel(target) {
    if (!target) return null;
    let panel = null;
    switch (rwphPhysicalPanelIdV1600(target)) {
      case "rw-payout-helper":
        panel = rwphCreateDefaultSetupActualMainPanel();
        break;
      case "rwph-results-panel":
        panel = rwphCreateDefaultSetupActualResultsPanel();
        break;
      case "rwph-newsletter-panel":
        panel = rwphOpenNewsletterPanelV1537(rwphDefaultSetupNewsletterDataV1554());
        break;
      case "rwph-newsletter-member-stats-panel": {
        const newsletterData = rwphDefaultSetupNewsletterDataV1554();
        panel = newsletterData ? rwphOpenNewsletterMemberStatsPanelV1553(newsletterData, new Set(), () => {}) : null;
        break;
      }
      case "rwph-results-loading-panel": {
        const previewTab = rwphCreateResultsLoadingPanel(buildResultsLoadingHtml("rwph-default-setup", Date.now()), Date.now(), { mode: "loading", setupPreview: true });
        panel = previewTab?.rwphPanel || document.getElementById("rwph-results-loading-panel");
        break;
      }
      case "rwph-basic-calculations-panel":
        panel = rwphCreateDefaultSetupActualCalculationPanel("standard");
        break;
      case "rwph-advanced-calculations-panel":
        panel = rwphCreateDefaultSetupActualCalculationPanel("points");
        break;
      case "rwph-saved-reports-panel":
        panel = await rwphOpenSavedReportsPanel({ setupMode: true });
        break;
      case "rwph-member-management-panel":
        panel = await rwphOpenMemberManagementPanel("points", { setupMode: true });
        break;
      case "rw-pay-all-panel":
        openPayAllCopyPanel(rwphDefaultSetupSampleRows());
        panel = document.getElementById("rw-pay-all-panel");
        break;
      case "rwph-xanax-send-status":
        sessionStorage.removeItem("rwph_xanax_helper_closed");
        panel = rwphRenderPaymentHelperPanel("RWPH-SETUP-CODE", "Default Setup preview. This is the real Xanax Payment Helper wizard; no payment is being created.", false, { setupPreview: true, daysPerItem: 10 });
        rwphSetupPaymentHelperPanelClicks("RWPH-SETUP-CODE");
        break;
      case "rwph-licence-info-panel":
        rwphOpenLicenceInfoPanel({ valid: true, name: "Example User", tornId: "1000001", expiresAt: Math.floor(Date.now() / 1000) + (30 * 86400) });
        panel = document.getElementById("rwph-licence-info-panel");
        break;
      case "rwph-layout-theme-panel":
        rwphOpenPanelThemePicker();
        panel = document.getElementById("rwph-layout-theme-panel");
        break;
      case "rwph-logo-picker-panel":
        rwphOpenLogoPicker();
        panel = document.getElementById("rwph-logo-picker-panel");
        break;
      case "rw-wrong-payment-panel":
        showWrongPaymentPanel("Default Setup preview. This is the real Payment Warning panel; no payment has been sent.");
        panel = document.getElementById("rw-wrong-payment-panel");
        break;
      case "rwph-default-setup-panel":
        // The actual admin setup *settings* panel is a valid user-positioned panel.
        // The separate setup controller is intentionally not a target; it must
        // remain available to advance/save each preview.
        rwphOpenDefaultSetupPanel(rwphDefaultSetupState?.adminKey || "");
        panel = document.getElementById("rwph-default-setup-panel");
        if (panel) {
          const start = panel.querySelector("#rwph-default-setup-start");
          if (start) {
            start.disabled = true;
            start.title = "Admin Default Setup is currently running. Finish from the controller.";
          }
          const status = panel.querySelector("#rwph-default-setup-status");
          if (status) status.textContent = "Layout preview: move and resize this panel, then use Next Panel on the setup controller.";
        }
        break;
      default:
        break;
    }
    if (!panel) return null;
    panel.dataset.rwphDefaultSetupPreview = "1"; // setup-managed real panel: do not overwrite this admin's personal layout.
    panel.dataset.rwphDefaultSetupActual = "1";
    panel.dataset.rwphDefaultSetupDevice = rwphDefaultSetupState?.device || "pc";
    if (target.page && panel.id === 'rw-pay-all-panel') {
      const state = panel.__rwphPayAllWizardStateV1600;
      if (state) {
        state.page = target.page;
        state.index = 0;
        panel.__rwphRenderPayAllWizardV1600?.();
      }
      rwphSetWizardLayoutPageV1600(panel, target.page, { setupPreview: true });
    } else if (target.page && panel.id === 'rwph-xanax-send-status') {
      const state = panel.__rwphPaymentWizardState;
      if (state) {
        state.page = target.page;
        if (target.page === 'licence') { state.mode = 'faction'; state.ownTornId = '1000001'; state.selected = ['1000001','1000002']; state.members = [
          { id: '1000001', name: 'Example Leader' }, { id: '1000002', name: 'Example Member' }
        ]; }
        rwphRenderPaymentHelperWizardV1568(panel);
      }
      rwphSetWizardLayoutPageV1600(panel, target.page, { setupPreview: true });
    }
    panel.style.setProperty("z-index", "2147483638", "important");
    panel.style.setProperty("pointer-events", "auto", "important");
    return panel;
  }

  async function rwphOpenDefaultSetupPreview() {
    const state = rwphDefaultSetupState;
    if (!state) return;
    rwphRemoveDefaultSetupPreview();
    const target = RWPH_DEFAULT_SETUP_PANEL_TARGETS[state.index];
    if (!target) {
      rwphFinishDefaultSetupWizard(false);
      return;
    }
    state.currentTarget = target;
    rwphPersistDefaultSetupWizard();
    if (rwphDefaultSetupNavigateForTarget(target)) return;

    const panel = await rwphOpenDefaultSetupActualPanel(target);
    if (!panel) {
      const controller = document.getElementById("rwph-default-setup-controller");
      const status = controller?.querySelector("#rwph-default-setup-controller-status");
      if (status) status.textContent = `Could not open the real ${target.label} panel. Press Next Panel to continue or Cancel to stop.`;
      rwphRaiseDefaultSetupController();
      return;
    }

    const inProgress = state.panels?.[target.id];
    const publishedLayouts = rwphGlobalPanelLayoutsCache.layouts?.[state.device]?.panels || {};
    const saved = inProgress || publishedLayouts[target.id] || (target.page ? publishedLayouts[rwphPhysicalPanelIdV1600(target)] : null);
    if (saved) rwphApplyPanelGeometry(panel, saved, { normalized: true });
    else rwphApplyPanelGeometry(panel, rwphDefaultSetupFallbackGeometry(target, state.device), { normalized: false });

    // Some real builders install their own drag/resize. Calling again is safe and guarantees setup-created results hosts have it.
    const handle = rwphPhysicalPanelIdV1600(target) === "rw-pay-all-panel" ? ".rw-pay-all-head"
      : target.id === "rwph-saved-reports-panel" ? ".rwph-panel-head, .rwph-floating-panel-head"
      : (target.id === "rwph-results-loading-panel" || target.id === "rwph-results-panel") ? ".rwph-panel-head, .rwph-results-panel-head"
      : rwphPhysicalPanelIdV1600(target) === "rwph-xanax-send-status" ? "#rwph-payment-helper-title"
      : ".rwph-panel-head, .rwph-floating-panel-head, .rw-head";
    rwphEnablePanelMoveResize(panel, handle);

    const controller = document.getElementById("rwph-default-setup-controller");
    const counter = controller?.querySelector("#rwph-default-setup-counter");
    const name = controller?.querySelector("#rwph-default-setup-current");
    const status = controller?.querySelector("#rwph-default-setup-controller-status");
    const next = controller?.querySelector("#rwph-default-setup-next");
    if (counter) counter.textContent = `Panel ${state.index + 1} of ${RWPH_DEFAULT_SETUP_PANEL_TARGETS.length}`;
    if (name) name.textContent = target.label;
    if (status) status.textContent = "Move/resize this actual panel, then press Next Panel to save its admin default. Your own saved panel layouts will not affect these previews.";
    if (next) next.textContent = state.index === RWPH_DEFAULT_SETUP_PANEL_TARGETS.length - 1 ? "Save Setup" : "Next Panel";
    rwphRaiseDefaultSetupController();
  }

  async function rwphAdvanceDefaultSetupWizard() {
    const state = rwphDefaultSetupState;
    if (!state) return;
    const target = state.currentTarget || RWPH_DEFAULT_SETUP_PANEL_TARGETS[state.index];
    const panel = target ? document.getElementById(rwphPhysicalPanelIdV1600(target)) : null;
    if (panel) {
      const geometry = rwphCaptureNormalizedPanelGeometry(panel);
      if (geometry) state.panels[target.id] = geometry;
    }
    rwphRemoveDefaultSetupPreview();
    state.index += 1;
    rwphPersistDefaultSetupWizard();
    if (state.index >= RWPH_DEFAULT_SETUP_PANEL_TARGETS.length) {
      await rwphFinishDefaultSetupWizard(false);
      return;
    }
    await rwphOpenDefaultSetupPreview();
  }

  function rwphCreateDefaultSetupController() {
    document.getElementById("rwph-default-setup-controller")?.remove();
    const state = rwphDefaultSetupState;
    if (!state) return null;
    const controller = document.createElement("aside");
    controller.id = "rwph-default-setup-controller";
    controller.className = "rwph-floating-panel rwph-default-setup-controller";
    controller.style.cssText = `
      position:fixed;
      z-index:2147483647;
      right:12px;
      top:12px;
      width:min(300px,calc(100vw - 20px));
      max-width:calc(100vw - 20px);
      min-width:min(240px,calc(100vw - 20px));
      min-height:0;
      max-height:calc(100vh - 24px);
      overflow:hidden;
      display:flex;
      flex-direction:column;
      box-sizing:border-box;
    `;
    controller.innerHTML = `
      <div class="rwph-panel-head" style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px;cursor:move;touch-action:none;user-select:none;">
        <div><b>Default Setup</b><div class="rw-muted" style="font-size:11px;">${rwphDefaultSetupDeviceLabel(state.device)}</div></div>
        <button id="rwph-default-setup-controller-close" type="button" class="danger" title="Cancel setup" aria-label="Cancel setup">×</button>
      </div>
      <div class="rwph-floating-panel-body rwph-default-setup-controller-body" style="padding:12px;display:grid;gap:9px;min-height:0;overflow-y:auto;overflow-x:hidden;box-sizing:border-box;">
        <div id="rwph-default-setup-counter" style="font-weight:900;">Panel 1 of ${RWPH_DEFAULT_SETUP_PANEL_TARGETS.length}</div>
        <div id="rwph-default-setup-current" style="font-size:14px;font-weight:900;">Starting...</div>
        <div id="rwph-default-setup-controller-status" class="rw-muted" style="line-height:1.4;overflow-wrap:anywhere;word-break:break-word;min-width:0;">Move/resize the panel, then press Next Panel.</div>
        <div class="rw-actions rwph-default-setup-controller-actions" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(110px,100%),1fr));gap:8px;width:100%;min-width:0;">
          <button id="rwph-default-setup-next" type="button" class="primary">Next Panel</button>
          <button id="rwph-default-setup-cancel" type="button" class="danger">Cancel</button>
        </div>
      </div>
    `;
    document.body.appendChild(controller);
    rwphEnablePanelMoveResize(controller, ".rwph-panel-head");
    rwphRaiseDefaultSetupController();
    controller.querySelector("#rwph-default-setup-next")?.addEventListener("click", () => {
      if (controller.dataset.rwphDefaultSetupDone === "1") {
        try { controller.remove(); } catch (_) {}
        rwphClearPersistedDefaultSetupWizard();
        rwphDefaultSetupState = null;
        rwphSetPanelOpenState(false);
        setLauncherOpenState(false);
        setTimeout(() => createPanel(), 80);
        return;
      }
      if (controller.dataset.rwphDefaultSetupRetry === "1") {
        controller.dataset.rwphDefaultSetupRetry = "0";
        rwphFinishDefaultSetupWizard(false);
        return;
      }
      rwphAdvanceDefaultSetupWizard();
    });
    controller.querySelector("#rwph-default-setup-cancel")?.addEventListener("click", () => rwphFinishDefaultSetupWizard(true));
    controller.querySelector("#rwph-default-setup-controller-close")?.addEventListener("click", () => rwphFinishDefaultSetupWizard(true));
    return controller;
  }

  async function rwphStartDefaultSetupWizard(device, adminKey) {
    if (rwphDefaultSetupState) return;
    const safeDevice = String(device || "").toLowerCase() === "mobile" ? "mobile" : "pc";
    await rwphFetchGlobalPanelLayouts(true).catch(() => {});
    rwphCloseDefaultSetupPanel();

    rwphRemoveDefaultSetupPreview();
    // Close any currently open target panels so the wizard can open the real panel cleanly one at a time.
    for (const target of RWPH_DEFAULT_SETUP_PANEL_TARGETS) {
      const existing = document.getElementById(target.id);
      if (existing) {
        try { existing.remove(); } catch (_) {}
      }
    }

    rwphSetPanelOpenState(false);
    setLauncherOpenState(false);
    rwphDefaultSetupState = {
      device: safeDevice,
      adminKey,
      index: 0,
      currentTarget: null,
      panels: {},
      homeUrl: rwphDefaultSetupCleanHomeUrl(window.location.href),
    };
    rwphPersistDefaultSetupWizard();
    rwphCreateDefaultSetupController();
    await rwphOpenDefaultSetupPreview();
  }

  function rwphOpenDefaultSetupPanel(adminKey) {
    rwphCloseDefaultSetupPanel();
    rwphEnsureFloatingPanelCss();
    const panel = document.createElement("section");
    panel.id = "rwph-default-setup-panel";
    panel.className = "rwph-floating-panel rwph-default-setup-panel";
    panel.style.cssText = `
      position:fixed;
      z-index:2147483644;
      right:18px;
      top:110px;
      width:min(480px,calc(100vw - 20px));
      height:min(500px,calc(100vh - 20px));
      min-width:min(300px,calc(100vw - 24px));
      min-height:300px;
      overflow:hidden;
      display:flex;
      flex-direction:column;
    `;
    panel.innerHTML = `
      <div class="rwph-panel-head" style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 13px;cursor:move;touch-action:none;user-select:none;">
        <div><b>Default Setup</b><div class="rw-muted" style="font-size:11px;">Global panel positions and sizes</div></div>
        <button id="rwph-default-setup-close" class="danger" type="button" title="Close" aria-label="Close">×</button>
      </div>
      <div class="rwph-floating-panel-body rwph-default-setup-panel-body" style="padding:14px;overflow-y:auto;overflow-x:hidden;flex:1 1 auto;min-height:0;box-sizing:border-box;">
        <div class="rw-card" style="padding:12px;margin-bottom:12px;">
          <b>Choose which default layout to edit.</b>
          <div class="rw-muted" style="margin-top:6px;line-height:1.45;">PC and Phone/PDA use completely separate saved defaults. For the most accurate result, run the PC setup on a PC and the Phone/PDA setup on a phone or Torn PDA. RWPH saves each user's panel positions and sizes separately on their own browser/device. These admin settings are the starting layout when no personal adjustment is saved. Users can select Restore Default Panel Positions on the main panel to return all panels to these published defaults.</div>
        </div>
        <label style="display:grid;gap:6px;margin-bottom:12px;">Setup type
          <select id="rwph-default-setup-device">
            <option value="pc"${rwphIsMobileOrPdaView() ? "" : " selected"}>PC</option>
            <option value="mobile"${rwphIsMobileOrPdaView() ? " selected" : ""}>Phone / PDA</option>
          </select>
        </label>
        <div id="rwph-default-setup-saved-summary" class="rw-card" style="padding:12px;margin-bottom:12px;">Loading current defaults...</div>
        <div class="rw-card" style="padding:12px;margin-bottom:12px;">
          <b>How it works</b>
          <ol style="margin:8px 0 0 20px;padding:0;line-height:1.55;">
            <li>Click Start Setup.</li>
            <li>RWPH opens all ${RWPH_DEFAULT_SETUP_PANEL_TARGETS.length} real script panels one at a time, including the calculation panels, every page of both payment wizards, and this Default Setup panel.</li>
            <li>Move and resize the actual panel to the default you want.</li>
            <li>Press Next Panel to save it and continue.</li>
            <li>After the last panel, the complete layout is saved to MySQL for everyone.</li>
          </ol>
        </div>
        <button id="rwph-default-setup-start" type="button" class="primary" style="width:100%;">Start Setup</button>
        <div id="rwph-default-setup-status" class="rw-muted" style="margin-top:10px;">Ready.</div>
      </div>
    `;
    document.body.appendChild(panel);
    rwphEnablePanelMoveResize(panel, ".rwph-panel-head");
    panel.querySelector("#rwph-default-setup-close")?.addEventListener("click", rwphCloseDefaultSetupPanel);

    const renderSummary = (layouts) => {
      const summary = panel.querySelector("#rwph-default-setup-saved-summary");
      if (!summary) return;
      const row = (device, label) => {
        const layout = layouts?.[device];
        const count = Object.keys(layout?.panels || {}).length;
        const when = layout?.updatedAt ? new Date(Number(layout.updatedAt)).toLocaleString() : "Not configured";
        return `<div style="display:flex;justify-content:space-between;gap:10px;padding:6px 0;"><b>${label}</b><span class="rw-muted">${count ? `${count} panels · ${esc(when)}` : "Not configured"}</span></div>`;
      };
      summary.innerHTML = `${row("pc", "PC")}${row("mobile", "Phone / PDA")}`;
    };
    renderSummary(rwphGlobalPanelLayoutsCache.layouts);
    rwphFetchGlobalPanelLayouts(true).then(renderSummary).catch(() => {
      const status = panel.querySelector("#rwph-default-setup-status");
      if (status) status.textContent = "Could not refresh saved defaults. You can still start setup; saving requires the updated backend.";
    });

    panel.querySelector("#rwph-default-setup-start")?.addEventListener("click", async () => {
      const button = panel.querySelector("#rwph-default-setup-start");
      const status = panel.querySelector("#rwph-default-setup-status");
      const device = panel.querySelector("#rwph-default-setup-device")?.value || "pc";
      if (button) button.disabled = true;
      if (status) status.textContent = `Starting ${rwphDefaultSetupDeviceLabel(device)} setup...`;
      try {
        await rwphStartDefaultSetupWizard(device, adminKey);
      } catch (e) {
        if (button) button.disabled = false;
        if (status) status.textContent = `Could not start setup: ${e.message}`;
      }
    });
  }

  function rwphSaveActiveTab(area, tabName) {
    const state = rwphSafeJsonGet(ACTIVE_TAB_STORAGE_KEY, {});
    state[area] = tabName;
    rwphSafeJsonSet(ACTIVE_TAB_STORAGE_KEY, state);
  }

  function rwphGetActiveTab(area, fallback) {
    const state = rwphSafeJsonGet(ACTIVE_TAB_STORAGE_KEY, {});
    return state[area] || fallback;
  }

  function rwphSavePayoutFormState() {
    const ids = ["rw-from", "rw-to", "rw-points-from", "rw-points-to", "rw-total", "rw-total-overall", "rw-points-total", "rw-points-total-overall", "rw-calculation-system", "rw-point-war-hit", "rw-point-assist", "rw-point-outside", "rw-point-retal", "rw-point-retal-mode", "rw-point-overseas", "rw-point-overseas-mode", "rw-point-outside-chain-only", "rw-point-hospital", "rw-point-enemy-hospital", "rw-point-respect", "rw-point-respect-step", "rw-point-respect-ignore-chain", "rw-point-respect-war-only", "rw-point-fair-fight", "rw-point-fair-fight-mode", "rw-point-fair-fight-linear-rate", "rw-point-fair-fight-avg-step", "rw-point-fair-fight-bonus-step", "rw-hybrid-participation-pct", "rw-hybrid-performance-pct", "rw-hybrid-war-pct", "rw-hybrid-support-pct", "rw-hybrid-retal-support", "rw-excluded-members", "rw-points-excluded-members"];
    const state = {};
    for (const id of ids) {
      const el = document.getElementById(id);
      if (!el) continue;
      state[id] = el.type === "checkbox" ? !!el.checked : String(el.value || "");
    }
    rwphSafeJsonSet(PAYOUT_FORM_STATE_STORAGE_KEY, state);
  }

  function rwphRestorePayoutFormState() {
    const state = rwphSafeJsonGet(PAYOUT_FORM_STATE_STORAGE_KEY, {});
    if (state["rw-total"] && !state["rw-points-total"]) state["rw-points-total"] = state["rw-total"];
    if (state["rw-total"] && !state["rw-total-overall"]) state["rw-total-overall"] = state["rw-total"];
    if (state["rw-points-total"] && !state["rw-points-total-overall"]) state["rw-points-total-overall"] = state["rw-points-total"];
    // Previously saved date/time values were interpreted in the browser's local
    // timezone. Convert once into UTC clock values, preserving the old instants.
    if (!GM_getValue("rwph-war-times-tct-migrated-v1592", false)) {
      for (const id of ["rw-from", "rw-to", "rw-points-from", "rw-points-to"]) {
        if (!state[id]) continue;
        const oldMs = new Date(String(state[id])).getTime();
        if (Number.isFinite(oldMs)) state[id] = toDateTimeLocalValue(oldMs / 1000);
      }
      rwphSafeJsonSet(PAYOUT_FORM_STATE_STORAGE_KEY, state);
      GM_setValue("rwph-war-times-tct-migrated-v1592", true);
    }
    if (state["rw-from"] && !state["rw-points-from"]) state["rw-points-from"] = state["rw-from"];
    if (state["rw-to"] && !state["rw-points-to"]) state["rw-points-to"] = state["rw-to"];
    if (GM_getValue(PAYOUT_FORM_SCHEMA_STORAGE_KEY, "") !== "shared-advanced-presets-v2") {
      if (String(state["rw-point-retal"] ?? "").trim() === "4") state["rw-point-retal"] = "0.2";
      const previousSystem = String(state["rw-calculation-system"] || "").trim();
      const legacySettingIds = ["rw-point-war-hit", "rw-point-assist", "rw-point-outside", "rw-point-retal", "rw-point-hospital", "rw-point-enemy-hospital", "rw-point-respect", "rw-point-respect-step", "rw-point-fair-fight", "rw-point-fair-fight-avg-step", "rw-point-fair-fight-bonus-step"];
      const hadLegacyAdvancedSettings = legacySettingIds.some((id) => Object.prototype.hasOwnProperty.call(state, id));
      const preserveExistingValues = previousSystem === "custom_advanced" || (!previousSystem && hadLegacyAdvancedSettings);
      const migratedSystem = preserveExistingValues ? "rwph_classic" : rwphNormalizeAdvancedCalculationSystem(previousSystem || "hybrid_hit_performance");
      state["rw-calculation-system"] = migratedSystem;
      const preset = RWPH_ADVANCED_SYSTEM_PRESETS[migratedSystem] || RWPH_ADVANCED_SYSTEM_PRESETS.hybrid_hit_performance;
      for (const [key, [id, property]] of Object.entries(RWPH_ADVANCED_PRESET_FIELD_MAP)) {
        if (!(key in preset)) continue;
        if (preserveExistingValues && Object.prototype.hasOwnProperty.call(state, id)) continue;
        state[id] = property === "checked" ? !!preset[key] : String(preset[key]);
      }
      GM_setValue(PAYOUT_FORM_SCHEMA_STORAGE_KEY, "shared-advanced-presets-v2");
      rwphSafeJsonSet(PAYOUT_FORM_STATE_STORAGE_KEY, state);
    }
    for (const [id, value] of Object.entries(state)) {
      const el = document.getElementById(id);
      if (!el) continue;
      if (el.type === "checkbox") el.checked = !!value;
      else if (value !== undefined && value !== null && String(value) !== "") el.value = String(value);
    }
  }

  function rwphAttachPayoutFormPersistence() {
    const ids = ["rw-from", "rw-to", "rw-points-from", "rw-points-to", "rw-total", "rw-total-overall", "rw-points-total", "rw-points-total-overall", "rw-calculation-system", "rw-point-war-hit", "rw-point-assist", "rw-point-outside", "rw-point-retal", "rw-point-retal-mode", "rw-point-overseas", "rw-point-overseas-mode", "rw-point-outside-chain-only", "rw-point-hospital", "rw-point-enemy-hospital", "rw-point-respect", "rw-point-respect-step", "rw-point-respect-ignore-chain", "rw-point-respect-war-only", "rw-point-fair-fight", "rw-point-fair-fight-mode", "rw-point-fair-fight-linear-rate", "rw-point-fair-fight-avg-step", "rw-point-fair-fight-bonus-step", "rw-hybrid-participation-pct", "rw-hybrid-performance-pct", "rw-hybrid-war-pct", "rw-hybrid-support-pct", "rw-hybrid-retal-support", "rw-excluded-members", "rw-points-excluded-members"];
    for (const id of ids) {
      const el = document.getElementById(id);
      if (!el || el.dataset.rwphPersistReady === "1") continue;
      el.dataset.rwphPersistReady = "1";
      el.addEventListener("input", rwphSavePayoutFormState);
      el.addEventListener("change", rwphSavePayoutFormState);
    }
  }

  function rwphBuildFourColourTheme(label, body, surface, text, outline) {
    const safeBody = rwphNormalizeHexColour(body, "#0d0f11");
    const safeSurface = rwphNormalizeHexColour(surface, "#20252a");
    const safeText = rwphNormalizeHexColour(text, "#f4f5f6");
    const safeOutline = rwphNormalizeHexColour(outline, "#e9bd4e");
    const accent2 = rwphMixHexColour(safeOutline, safeText, 0.24);
    return {
      label,
      layoutName: "RWPH three-colour theme",
      bg: safeBody,
      bg2: rwphMixHexColour(safeBody, safeSurface, 0.22),
      panel: safeSurface,
      panel2: safeSurface,
      panel3: rwphMixHexColour(safeSurface, safeOutline, 0.10),
      line: rwphHexToRgba(safeOutline, 0.42),
      line2: rwphHexToRgba(safeOutline, 0.68),
      text: safeText,
      soft: rwphMixHexColour(safeText, safeBody, 0.30),
      accent: safeOutline,
      accent2,
      good: safeOutline,
      danger: safeOutline,
      radius: "12px",
      cardRadius: "10px",
      buttonRadius: "8px",
      borderWidth: "1px",
      borderStyle: "solid",
      buttonCase: "none",
      buttonTracking: ".01em",
      texture: "",
      headerTexture: "",
      cardTexture: "",
      buttonTexture: "",
      masterColours: {
        base: safeBody,
        body: safeBody,
        surface: safeSurface,
        text: safeText,
        outline: safeOutline,
      },
    };
  }

