  function rwphAdvancedHelpText(help) {
    try {
      return typeof help?.message === "function" ? help.message() : String(help?.message || "No help is available for this setting yet.");
    } catch (_) {
      return "No help is available for this setting yet.";
    }
  }

  function rwphAttachAdvancedSettingHelpButtons() {
    const panel = document.getElementById("rw-payout-helper");
    if (!panel) return;

    Object.entries(RWPH_ADVANCED_SETTING_HELP).forEach(([id, help]) => {
      const control = document.getElementById(id);
      if (!control) return;
      const label = control.closest("label");
      if (!label || label.querySelector(`[data-rwph-help-for="${id}"]`)) return;

      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "rwph-setting-help-button";
      btn.dataset.rwphHelpFor = id;
      btn.textContent = "?";
      btn.title = `Explain ${help.title || "this setting"}`;
      btn.setAttribute("aria-label", `Explain ${help.title || "this setting"}`);
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const currentPopup = document.getElementById("rwph-info-popup-panel-live");
        if (currentPopup?.dataset?.rwphHelpFor === id) {
          if (typeof currentPopup.__rwphClose === "function") currentPopup.__rwphClose();
          else currentPopup.remove();
          return;
        }
        const popup = rwphShowToast(
          rwphAdvancedHelpText(help),
          "info",
          help.title || "Advanced Setting",
          { persistent: true }
        );
        if (popup) popup.dataset.rwphHelpFor = id;
      });

      const isCheckbox = String(control.type || "").toLowerCase() === "checkbox";
      // The v1.1.592 TCT picker wraps date/time inputs in a nested element.
      // insertBefore(reference=control) fails if that input isn't a direct
      // child of label. Always use the direct child wrapping the control.
      const labelChild = control.parentElement === label
        ? control : Array.from(label.children).find(child => child.contains(control));
      if (!labelChild) return;
      const titleLine = document.createElement("span");
      titleLine.className = "rwph-setting-label-line";
      titleLine.dataset.rwphHelpLineFor = id;

      if (isCheckbox && labelChild === control) {
        const titleNodes = [];
        let node = control.nextSibling;
        while (node) {
          const next = node.nextSibling;
          titleNodes.push(node);
          node = next;
        }
        label.insertBefore(titleLine, control.nextSibling);
        titleNodes.forEach(item => titleLine.appendChild(item));
        titleLine.appendChild(btn);
      } else {
        const titleNodes = [];
        let node = label.firstChild;
        while (node && node !== labelChild) {
          const next = node.nextSibling;
          titleNodes.push(node);
          node = next;
        }
        label.insertBefore(titleLine, labelChild);
        titleNodes.forEach(item => titleLine.appendChild(item));
        titleLine.appendChild(btn);
      }
    });

    const reset = panel.querySelector("#rw-points-reset-recommended");
    if (reset && reset.dataset.rwphAdvancedResetReady !== "1") {
      reset.dataset.rwphAdvancedResetReady = "1";
      reset.addEventListener("click", (event) => {
        event.preventDefault();
        const selectedSystem = rwphNormalizeAdvancedCalculationSystem(reset.dataset.rwphCalculationSystem || rwphAdvancedCalculationSystem());
        rwphApplyAdvancedSystemPreset(selectedSystem, { notify: true });
      });
    }
  }

  function attachMoveLauncherButton() {
    ["rw-move-launcher", "rw-move-launcher-admin"].forEach((id) => {
      const btn = document.getElementById(id);
      if (!btn || btn.dataset.rwphCornerReady === "1") return;
      btn.dataset.rwphCornerReady = "1";
      btn.addEventListener("click", cycleLauncherCorner);
    });
    updateLauncherCornerButtonLabels();
  }

  function closePanel() {
    try { rwphCloseAllCalculationSettingsPanels(); } catch (_) {}
    const panel = document.getElementById("rw-payout-helper");
    if (panel) {
      panel.remove();
    }
    rwphSetPanelOpenState(false);
    setLauncherOpenState(false);
  }

  function togglePanel() {
    const panel = document.getElementById("rw-payout-helper");

    if (panel) {
      closePanel();
      return;
    }

    createPanel();
  }

  const rwphApiPostInFlight = new Map();

  function rwphApiPostRequestKey(path, body) {
    let payload = "";
    try { payload = JSON.stringify(body || {}); } catch (_) { payload = String(body || ""); }
    return `${String(path || "")}|${payload}`;
  }

  function apiPost(path, body) {
    const requestKey = rwphApiPostRequestKey(path, body);
    const existing = rwphApiPostInFlight.get(requestKey);
    if (existing) return existing;

    const promise = new Promise((resolve, reject) => {
      const safePath = String(path || "");
      const requestTimeout = safePath === "/api/paywall/verify-token" ? 20000
        : safePath === "/api/paywall/start" ? 30000
        : (safePath.includes("/api/calc/") ? 300000 : 120000);
      GM_xmlhttpRequest({
        method: "POST",
        url: `${PAYWALL_API_BASE}${path}`,
        headers: { "Content-Type": "application/json" },
        data: JSON.stringify(body || {}),
        timeout: requestTimeout,
        onload: (res) => {
          try {
            const json = JSON.parse(res.responseText || "{}");
            if (!json.ok) {
              const err = new Error(json.error || `Server error ${res.status}`);
              err.retryAfterSeconds = Number(json.retryAfterSeconds || 0);
              err.cooldownEndsAtMs = Number(json.cooldownEndsAtMs || 0);
              err.status = Number(res.status || 0);
              err.code = String(json.code || "");
              err.cacheId = Number(json.cacheId || 0);
              reject(err);
            } else {
              resolve(json);
            }
          } catch (e) {
            reject(new Error(`Could not parse server response. Status ${res.status}.`));
          }
        },
        onerror: () => reject(new Error("Failed to reach paywall server.")),
        ontimeout: () => reject(new Error("Paywall server request timed out. On phone/Torn PDA, large wars or Torn API delays can take longer; try again in a moment.")),
      });
    });

    rwphApiPostInFlight.set(requestKey, promise);
    const clear = () => {
      if (rwphApiPostInFlight.get(requestKey) === promise) rwphApiPostInFlight.delete(requestKey);
    };
    promise.then(clear, clear);
    return promise;
  }

  function apiPostCancelable(path, body, options = {}) {
    let request = null;
    let settled = false;
    const promise = new Promise((resolve, reject) => {
      const safePath = String(path || "");
      const requestTimeout = Number(options.timeout || 0) > 0 ? Number(options.timeout) : (safePath.includes("/api/calc/") ? 600000 : 120000);
      request = GM_xmlhttpRequest({
        method: "POST",
        url: `${PAYWALL_API_BASE}${path}`,
        headers: { "Content-Type": "application/json" },
        data: JSON.stringify(body || {}),
        timeout: requestTimeout,
        onload: (res) => {
          settled = true;
          try {
            const json = JSON.parse(res.responseText || "{}");
            if (!json.ok) {
              const err = new Error(json.error || `Server error ${res.status}`);
              err.retryAfterSeconds = Number(json.retryAfterSeconds || 0);
              err.cooldownEndsAtMs = Number(json.cooldownEndsAtMs || 0);
              err.status = Number(res.status || 0);
              err.code = String(json.code || "");
              err.cacheId = Number(json.cacheId || 0);
              err.cancelled = !!json.cancelled;
              reject(err);
            } else {
              resolve(json);
            }
          } catch (e) {
            reject(new Error(`Could not parse server response. Status ${res.status}.`));
          }
        },
        onerror: () => { settled = true; reject(new Error("Failed to reach paywall server.")); },
        ontimeout: () => { settled = true; reject(new Error("Paywall server request timed out. On phone/Torn PDA, large wars or Torn API delays can take longer; try again in a moment.")); },
        onabort: () => { settled = true; const err = new Error("Calculation cancelled because the Results Loading panel was closed."); err.cancelled = true; reject(err); },
      });
    });
    return {
      promise,
      abort: () => {
        if (settled) return;
        try { if (request && typeof request.abort === "function") request.abort(); } catch (_) {}
      },
    };
  }

  function rwphSendCalcCancel(progressId, reason = "Results Loading panel closed before calculation finished.") {
    const id = String(progressId || "").trim();
    if (!id) return;
    try {
      GM_xmlhttpRequest({
        method: "POST",
        url: `${PAYWALL_API_BASE}/api/calc/cancel`,
        headers: { "Content-Type": "application/json" },
        data: JSON.stringify({ progressId: id, reason }),
        timeout: 10000,
        onload: () => {},
        onerror: () => {},
        ontimeout: () => {},
      });
    } catch (_) {}
  }

  function rwphCleanResponsePreview(text, maxLen = 260) {
    return String(text || "")
      .replace(/<script[\s\S]*?<\/script>/gi, "")
      .replace(/<style[\s\S]*?<\/style>/gi, "")
      .replace(/<[^>]+>/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, maxLen);
  }

  function rwphParseAdminJsonResponse(res) {
    const raw = String(res?.responseText ?? res?.response ?? "");
    const trimmed = raw.trim();

    if (!trimmed) {
      throw new Error(`Admin server returned an empty response. Status ${res?.status || 0}. Make sure the backend/admin route is running.`);
    }

    try {
      return JSON.parse(trimmed);
    } catch (_) {}

    // Some mobile/PDA/tunnel wrappers can return text around the JSON. Try to salvage the JSON object before failing.
    const firstBrace = trimmed.indexOf("{");
    const lastBrace = trimmed.lastIndexOf("}");
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      const possibleJson = trimmed.slice(firstBrace, lastBrace + 1);
      try {
        return JSON.parse(possibleJson);
      } catch (_) {}
    }

    const preview = rwphCleanResponsePreview(trimmed);
    const looksHtml = /<\s*!doctype|<\s*html|ngrok|browser warning|tunnel/i.test(trimmed);
    if (looksHtml) {
      throw new Error(`Admin server returned HTML instead of JSON. Status ${res?.status || 0}. Check the backend URL/tunnel is pointing to the RWPH server and restart the server if needed. Response: ${preview || "HTML page"}`);
    }

    throw new Error(`Could not parse admin server response. Status ${res?.status || 0}. Response: ${preview || "No readable response text"}`);
  }

  function adminRequest(method, path, adminKey, body = {}) {
    return new Promise((resolve, reject) => {
      const isGet = String(method).toUpperCase() === "GET";
      const sep = path.includes("?") ? "&" : "?";
      const url = isGet
        ? `${PAYWALL_API_BASE}${path}${sep}adminKey=${encodeURIComponent(adminKey)}&_rwph=${Date.now()}`
        : `${PAYWALL_API_BASE}${path}`;

      GM_xmlhttpRequest({
        method,
        url,
        responseType: "text",
        headers: {
          "Accept": "application/json, text/plain, */*",
          "Content-Type": "application/json",
          "x-admin-key": adminKey,
          "ngrok-skip-browser-warning": "true",
          "Cache-Control": "no-cache",
        },
        data: isGet ? undefined : JSON.stringify({ ...(body || {}), adminKey, _rwph: Date.now() }),
        timeout: 120000,
        onload: (res) => {
          try {
            const json = rwphParseAdminJsonResponse(res);
            if (!json.ok) {
              const err = new Error(json.error || `Admin server error ${res.status}`);
              err.status = Number(res.status || 0);
              reject(err);
            } else {
              resolve(json);
            }
          } catch (e) {
            reject(e);
          }
        },
        onerror: () => reject(new Error("Failed to reach admin server. Check the backend/tunnel URL and @connect domain.")),
        ontimeout: () => reject(new Error("Admin server request timed out.")),
      });
    });
  }

  function formatUnixDate(unixSeconds) {
    if (!unixSeconds) return "Unknown";
    return new Date(Number(unixSeconds) * 1000).toLocaleString();
  }

  async function grantOwnerLicenseFromAdminKey(adminKey, statusEl) {
    if (!adminKey) throw new Error("Enter your admin key first.");

    const result = await adminRequest("POST", "/api/admin/grant-owner", adminKey, { days: 10000 });

    // v1.1.483: grant-owner now returns a freshly signed owner token in the same
    // response. Store it immediately so the 9999+ day licence is available
    // locally without a second paywall verification round-trip.
    if (result?.token) GM_setValue(PAYWALL_TOKEN_STORAGE_KEY, result.token);
    if (result?.expiresAt) rwphScheduleLicenseLockback(result.expiresAt);

    if (statusEl) {
      const timeLeft = result?.expiresAt ? formatLicenseDaysLeft(result.expiresAt) : "active";
      rwphToastPanelInfo(
        statusEl,
        `Admin access unlocked. Owner licence active for ${timeLeft}.`,
        "info",
        "RWPH Admin"
      );
    }

    return result;
  }

  async function extendAdminLicenseFromCurrentForm(statusEl, skipConfirm = false) {
    const adminKey = document.getElementById("rw-admin-key")?.value.trim();
    const tornId = document.getElementById("rw-admin-torn-id")?.value.trim();
    const name = document.getElementById("rw-admin-name")?.value.trim() || `User ${tornId}`;
    const days = Number(document.getElementById("rw-admin-days")?.value || 30);

    if (!adminKey) throw new Error("Enter your admin key first.");
    if (!tornId) throw new Error("Enter a Torn ID first.");
    if (!days || days <= 0) throw new Error("Enter valid extension days.");

    if (!skipConfirm && !confirm(`Extend license for ${name} (${tornId}) by ${days} day(s)?`)) return null;

    GM_setValue(ADMIN_KEY_STORAGE_KEY, adminKey);
    if (statusEl) statusEl.textContent = `Extending ${name} (${tornId}) by ${days} day(s)...`;

    const result = await adminRequest("POST", "/api/admin/extend", adminKey, { tornId, name, days });

    if (statusEl) {
      const previousText = result.previousExpiresAt ? ` Previous expiry: ${formatUnixDate(result.previousExpiresAt)}.` : "";
      rwphToastPanelInfo(
        statusEl,
        `Extended license for ${result.name || name} (${result.tornId || tornId}) by ${result.days || days} day(s).${previousText} New expiry: ${formatUnixDate(result.expiresAt)}.`,
        "info",
        "RWPH Admin"
      );
    }

    return result;
  }

  async function removeAdminLicenseDaysFromCurrentForm(statusEl, skipConfirm = false) {
    const adminKey = document.getElementById("rw-admin-key")?.value.trim();
    const tornId = document.getElementById("rw-admin-torn-id")?.value.trim();
    const name = document.getElementById("rw-admin-name")?.value.trim() || `User ${tornId}`;
    const days = Number(document.getElementById("rw-admin-days")?.value || 30);

    if (!adminKey) throw new Error("Enter your admin key first.");
    if (!tornId) throw new Error("Enter a Torn ID first.");
    if (!days || days <= 0) throw new Error("Enter valid days to remove.");

    if (!skipConfirm && !confirm(`Remove ${days} licence day(s) from ${name} (${tornId})?`)) return null;

    GM_setValue(ADMIN_KEY_STORAGE_KEY, adminKey);
    if (statusEl) statusEl.textContent = `Removing ${days} licence day(s) from ${name} (${tornId})...`;

    const result = await adminRequest("POST", "/api/admin/remove", adminKey, { tornId, name, days });

    if (statusEl) {
      const previousText = result.previousExpiresAt ? ` Previous expiry: ${formatUnixDate(result.previousExpiresAt)}.` : "";
      const endedText = result.expiredNow ? " Licence is now expired." : "";
      rwphToastPanelInfo(
        statusEl,
        `Removed ${result.days || days} licence day(s) from ${result.name || name} (${result.tornId || tornId}).${previousText} New expiry: ${formatUnixDate(result.expiresAt)}.${endedText}`,
        result.expiredNow ? "warn" : "info",
        "RWPH Admin"
      );
    }

    return result;
  }

  function renderAdminLicenses(licenses) {
    if (!licenses || !licenses.length) {
      return `<div class="rw-muted">No active licenses found.</div>`;
    }

    const sorted = [...licenses].sort((a, b) => Number(b.expiresAt || 0) - Number(a.expiresAt || 0));

    return `
      <div class="rw-admin-list">
        ${sorted.map((license) => `
          <div class="rw-admin-license-card">
            <div class="rw-admin-license-top">
              <div>
                <div class="rw-admin-license-name">${esc(license.name || `User ${license.tornId}`)}</div>
                <div class="rw-result-id">Torn ID: ${esc(license.tornId || "unknown")}</div>
              </div>
              <div style="display:flex; gap:4px; flex-wrap:wrap; justify-content:flex-end;">
                <button class="secondary rw-admin-fill-revoke" data-torn-id="${esc(license.tornId || "")}" data-name="${esc(license.name || `User ${license.tornId}`)}" style="margin:0;padding:5px 8px;">Fill</button>
              </div>
            </div>
            <div class="rw-muted" style="margin-top:6px;">
              Days left: ${esc(formatLicenseDaysLeft(license.expiresAt))}<br>
              Expires: ${esc(formatUnixDate(license.expiresAt))}<br>
              ${license.manualGrant ? "Manual grant" : "Payment/license record"}
            </div>
          </div>
        `).join("")}
      </div>
    `;
  }

  function rwphScheduleLicenseLockback(expiresAt) {
    const exp = Number(expiresAt || 0);
    if (window.__rwphLicenseExpiryTimer) {
      clearTimeout(window.__rwphLicenseExpiryTimer);
      window.__rwphLicenseExpiryTimer = null;
    }

    if (!Number.isFinite(exp) || exp <= 0) return;

    const msUntilExpiry = (exp * 1000) - Date.now();
    if (msUntilExpiry <= 0) {
      returnToLockedPanel("Your licence has expired. Buy Licence or extend your licence to unlock RWPH again.");
      return;
    }

    window.__rwphLicenseExpiryTimer = setTimeout(() => {
      returnToLockedPanel("Your licence has expired. Buy Licence or extend your licence to unlock RWPH again.");
    }, Math.min(msUntilExpiry + 1000, 2147483647));
  }

  function rwphReadManualLicenseCheckTimes() {
    try {
      const raw = GM_getValue(LICENSE_CHECK_RATE_STORAGE_KEY, "[]");
      const arr = Array.isArray(raw) ? raw : JSON.parse(String(raw || "[]"));
      return arr.map((x) => Number(x || 0)).filter((x) => Number.isFinite(x) && x > 0);
    } catch (_) {
      return [];
    }
  }

  function rwphWriteManualLicenseCheckTimes(times) {
    try { GM_setValue(LICENSE_CHECK_RATE_STORAGE_KEY, JSON.stringify((times || []).slice(-5))); } catch (_) {}
  }

  function rwphTryUseManualLicenseCheck(statusEl, buttonEl) {
    const nowMs = Date.now();
    const windowMs = 60 * 1000;
    const limit = 2;
    const fresh = rwphReadManualLicenseCheckTimes().filter((ts) => nowMs - ts < windowMs);
    if (fresh.length >= limit) {
      const waitSeconds = Math.max(1, Math.ceil((windowMs - (nowMs - fresh[0])) / 1000));
      const message = `Your Expiration can only be checked ${limit} times per minute. Try again in ${waitSeconds} second${waitSeconds === 1 ? "" : "s"}.`;
      if (statusEl) statusEl.textContent = message;
      if (buttonEl) {
        buttonEl.disabled = true;
        const originalText = buttonEl.dataset.rwphOriginalText || buttonEl.textContent || "Your Expiration";
        buttonEl.dataset.rwphOriginalText = originalText;
        buttonEl.textContent = `Wait ${waitSeconds}s`;
        setTimeout(() => {
          if (!buttonEl.isConnected) return;
          buttonEl.disabled = false;
          buttonEl.textContent = buttonEl.dataset.rwphOriginalText || "Your Expiration";
        }, Math.min(waitSeconds * 1000, 60000));
      }
      return false;
    }
    fresh.push(nowMs);
    rwphWriteManualLicenseCheckTimes(fresh);
    if (buttonEl) {
      buttonEl.disabled = true;
      setTimeout(() => { if (buttonEl.isConnected) buttonEl.disabled = false; }, 1200);
    }
    return true;
  }

  let rwphRecentVerifiedLicence = null;
  const RWPH_LAST_VERIFIED_KEY = "rwph_server_verified_licence_v1";
  const RWPH_TRANSIENT_GRACE_MS = 5 * 60 * 1000;
  function rwphLastRecentlyVerifiedLicence(token, userKey) {
    let saved = rwphRecentVerifiedLicence;
    if (!saved) {
      try { saved = GM_getValue(RWPH_LAST_VERIFIED_KEY, null); } catch (_) { saved = null; }
    }
    if (!saved || !token || saved.token !== token || saved.userKey !== userKey ||
      Date.now() - Number(saved.verifiedAtMs || 0) > RWPH_TRANSIENT_GRACE_MS ||
      Number(saved.info?.expiresAt || 0) <= Math.floor(Date.now() / 1000)) return null;
    return { ...saved.info, valid: true, transient: true, recentlyVerified: true };
  }
  async function getSavedLicenseInfo(forceFresh = false) {
    const token = GM_getValue(PAYWALL_TOKEN_STORAGE_KEY, "");
    const userKey =
      document.getElementById("rw-key")?.value.trim() ||
      document.getElementById("rw-paywall-key")?.value.trim() ||
      GM_getValue(STORAGE_KEY, "");

    // Only reuse a successful server verification for 20 seconds in the same tab.
    // Never cache failures, unsigned states, or an expired token. Explicit checks bypass this.
    if (!forceFresh && token && rwphRecentVerifiedLicence &&
        rwphRecentVerifiedLicence.token === token &&
        rwphRecentVerifiedLicence.userKey === userKey &&
        Date.now() - rwphRecentVerifiedLicence.verifiedAtMs < 20000 &&
        Number(rwphRecentVerifiedLicence.info.expiresAt || 0) > Math.floor(Date.now() / 1000)) {
      return { ...rwphRecentVerifiedLicence.info };
    }

    if (!token && !userKey) {
      return { valid: false, error: "No saved license token or Torn API key found. Buy Licence or paste your Torn API key first." };
    }

    try {
      const result = await apiPost("/api/paywall/verify-token", { token, userKey });
      if (result.valid && Number(result.expiresAt || 0) <= Math.floor(Date.now() / 1000)) {
        GM_setValue(PAYWALL_TOKEN_STORAGE_KEY, "");
        return { valid: false, error: "License expired." };
      }
      if (result.valid && result.token) GM_setValue(PAYWALL_TOKEN_STORAGE_KEY, result.token);
      if (result.valid && result.expiresAt) rwphScheduleLicenseLockback(result.expiresAt);
      rwphRecentVerifiedLicence = result.valid && result.token && Number(result.expiresAt || 0) > Math.floor(Date.now() / 1000)
        ? { token: result.token, userKey, verifiedAtMs: Date.now(), info: { ...result } } : null;
      if (rwphRecentVerifiedLicence) GM_setValue(RWPH_LAST_VERIFIED_KEY, rwphRecentVerifiedLicence);
      else GM_setValue(RWPH_LAST_VERIFIED_KEY, null);
      return result;
    } catch (e) {
      // Brief network/Hyperdrive failures do not prove an existing licence was revoked.
      // The five-minute grace opens the UI only; all protected backend actions still
      // validate their licence server-side and cannot be performed while offline.
      const recent = !forceFresh ? rwphLastRecentlyVerifiedLicence(token, userKey) : null;
      if (recent) return { ...recent, warning: e.message || "Licence server temporarily unavailable." };
      return { valid: false, transient: true, error: e.message || "Licence verification temporarily unavailable." };
    }
  }

  function formatLicenseDaysLeft(expiresAt) {
    const secondsLeft = Number(expiresAt || 0) - Math.floor(Date.now() / 1000);
    if (!Number.isFinite(secondsLeft) || secondsLeft <= 0) return "Expired";

    const days = Math.floor(secondsLeft / 86400);
    const hours = Math.floor((secondsLeft % 86400) / 3600);

    if (days >= 1) return `${days} day${days === 1 ? "" : "s"}, ${hours} hour${hours === 1 ? "" : "s"}`;
    if (hours >= 1) return `${hours} hour${hours === 1 ? "" : "s"}`;
    return "Under 1 hour";
  }

  function rwphCloseLicenceInfoPanel() {
    document.getElementById("rwph-licence-info-panel")?.remove();
  }

  function rwphOpenLicenceInfoPanel(info = {}) {
    rwphCloseLicenceInfoPanel();
    rwphEnsureFloatingPanelCss();

    const valid = info.valid === true;
    const userName = info.name || "this user";
    const tornId = info.tornId || "unknown";
    const expiresText = info.expiresAt ? formatUnixDate(info.expiresAt) : "No active expiry found";
    const timeLeft = info.expiresAt ? formatLicenseDaysLeft(info.expiresAt) : "No active licence";

    const panel = document.createElement("div");
    panel.id = "rwph-licence-info-panel";
    panel.className = "rwph-floating-panel rwph-licence-info-panel";
    panel.style.cssText = `
      position: fixed;
      z-index: 1000003;
      left: 50%;
      top: 50%;
      transform: translate(-50%, -50%);
      width: min(520px, calc(100vw - 18px));
      max-height: min(620px, calc(100vh - 18px));
      overflow: hidden;
      border-radius: 22px;
      border: 1px solid rgba(245,158,11,.35);
      color: #fff7ed;
      font-family: Inter, Segoe UI, Arial, sans-serif;
    `;
    panel.innerHTML = `
      <style>
        #rwph-licence-info-panel * { box-sizing: border-box; }
        #rwph-licence-info-panel .rwph-panel-head { position:relative;display:flex;align-items:center;justify-content:center;gap:10px;padding:14px 56px 12px 56px;border-bottom:1px solid rgba(255,255,255,.10);cursor:move;touch-action:none;-webkit-user-select:none;user-select:none;min-height:142px; }
        #rwph-licence-info-panel .rwph-panel-title { display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;font-weight:950;font-size:18px;color:#fff;text-align:center;min-width:0;width:100%; }
        #rwph-licence-info-panel .rwph-panel-title img { width:min(360px,86vw);height:96px;object-fit:contain;filter:none;pointer-events:none;background:transparent;box-shadow:none;border:0; }
        #rwph-licence-info-panel .rwph-panel-title span { display:block;width:100%;text-align:center;line-height:1.15;text-transform:uppercase;letter-spacing:.04em; }
        #rwph-licence-info-panel .rwph-floating-panel-body { padding:14px; overflow-y:auto; overflow-x:hidden; max-height:calc(100vh - 92px); }
        #rwph-licence-info-panel .rwph-licence-status-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-bottom:10px; }
        #rwph-licence-info-panel .rw-card { border:1px solid rgba(255,255,255,.10);border-radius:14px;padding:10px;background:rgba(15,23,42,.54); }
        #rwph-licence-info-panel .rwph-stat-label { font-size:11px;color:#b9dcff;font-weight:800;margin-bottom:3px; }
        #rwph-licence-info-panel .rwph-stat-value { font-size:13px;color:#fff;font-weight:950;line-height:1.35; }
        #rwph-licence-info-panel .rwph-licence-note { font-size:12px;line-height:1.45;color:#c7e8ff;margin:4px 0 8px; }
        #rwph-licence-info-panel .rwph-licence-actions { display:flex;justify-content:flex-end;gap:8px;margin-top:12px; }
        #rwph-licence-info-panel #rwph-licence-info-close { position:absolute;right:10px;top:10px;min-width:42px;width:42px;height:42px;font-size:18px;padding:0;z-index:50;display:grid;place-items:center; }
        @media (max-width:520px){ #rwph-licence-info-panel .rwph-licence-status-grid{grid-template-columns:1fr;} #rwph-licence-info-panel .rwph-panel-head{min-height:122px;padding:12px 48px 10px 48px;} #rwph-licence-info-panel .rwph-panel-title img{width:min(300px,82vw);height:78px;} }
      </style>
      <div class="rwph-panel-head">
        <div class="rwph-panel-title"><img class="rwph-dynamic-logo-icon" src="${rwphCurrentLogoIconUri()}" alt="RWPH"><span>Your Licence Info</span></div>
        <button id="rwph-licence-info-close" class="danger" type="button" title="Close" aria-label="Close">×</button>
      </div>
      <div class="rwph-floating-panel-body">
        ${valid ? "" : `<div class="rw-card" style="border-color:rgba(239,68,68,.55);margin-bottom:10px;"><b>Licence check:</b> ${esc(info.error || "No active saved licence found.")}</div>`}
        <div class="rw-card rwph-licence-note">This panel only shows your RWPH licence state. Extend Licence from the main panel when you want to add time; Torn item sending/confirmation remains manual.</div>
        <div class="rwph-licence-status-grid">
          <div class="rw-card"><div class="rwph-stat-label">User</div><div class="rwph-stat-value">${esc(userName)} (${esc(tornId)})</div></div>
          <div class="rw-card"><div class="rwph-stat-label">Licence status</div><div class="rwph-stat-value">${valid ? "Active" : "Not active"}</div></div>
          <div class="rw-card"><div class="rwph-stat-label">Time left</div><div class="rwph-stat-value">${esc(timeLeft)}</div></div>
          <div class="rw-card"><div class="rwph-stat-label">Expires</div><div class="rwph-stat-value">${esc(expiresText)}</div></div>
          <div class="rw-card"><div class="rwph-stat-label">Base licence</div><div class="rwph-stat-value">10 days per Xanax</div></div>
        </div>
      </div>
    `;
    document.body.appendChild(panel);
    panel.querySelector("#rwph-licence-info-close")?.addEventListener("click", rwphCloseLicenceInfoPanel);
    rwphEnablePanelMoveResize(panel, ".rwph-panel-head");
  }

  async function showLicenseDays(statusEl) {
    const info = await getSavedLicenseInfo(true);

    if (!info.valid) {
      rwphOpenLicenceInfoPanel(info || {});
      if (statusEl) statusEl.textContent = "Licence info panel opened.";
      if (document.getElementById("rw-key")) {
        const lockMsg = info.revoked
          ? "Your licence was revoked by an admin. Buy Licence or contact the owner to unlock RWPH again."
          : "Your licence has expired. Buy Licence or extend your licence to unlock RWPH again.";
        returnToLockedPanel(lockMsg);
      }
      return false;
    }

    rwphOpenLicenceInfoPanel(info || {});
    if (statusEl) statusEl.textContent = "Licence info panel opened.";
    return true;
  }

  function returnToLockedPanel(message = "Your licence has expired or was revoked. Buy Licence to unlock RWPH again.") {
    rwphRecentVerifiedLicence = null;
    GM_setValue(RWPH_LAST_VERIFIED_KEY, null);
    GM_setValue(PAYWALL_TOKEN_STORAGE_KEY, "");
    if (window.__rwphLicenseMonitor) {
      clearInterval(window.__rwphLicenseMonitor);
      window.__rwphLicenseMonitor = null;
    }
    if (window.__rwphLicenseExpiryTimer) {
      clearTimeout(window.__rwphLicenseExpiryTimer);
      window.__rwphLicenseExpiryTimer = null;
    }

    const panel = document.getElementById("rw-payout-helper");
    if (!panel) return;

    showPaywallScreen(panel, { skipAutoUnlock: true });
    setTimeout(() => {
      const status = document.getElementById("rw-paywall-status");
      if (status) status.textContent = message;
    }, 0);
  }

  function startLicenseExpiryMonitor() {
    if (window.__rwphLicenseMonitor) clearInterval(window.__rwphLicenseMonitor);

    const checkLicenseNow = async () => {
      const panel = document.getElementById("rw-payout-helper");
      if (!panel || !document.getElementById("rw-key")) return;

      const info = await getSavedLicenseInfo();
      if (info.transient) {
        // Keep the current panel usable on brief Cloudflare/MySQL/Torn outages.
        // The previously verified expiration timer stays active; the next monitor tick retries.
        console.warn("RWPH: temporary licence verification failure; retaining current panel until the next check:", info.error);
        return;
      }
      if (!info.valid) {
        const lockMsg = info.revoked
          ? "Your licence was revoked by an admin. Buy Licence or contact the owner to unlock RWPH again."
          : "Your licence has expired or is no longer active. Buy Licence or extend your licence to unlock RWPH again.";
        returnToLockedPanel(lockMsg);
        return;
      }
      if (info.expiresAt) rwphScheduleLicenseLockback(info.expiresAt);
    };

    // Licence is already verified when the panel opens. Keep the monitor slow so it does not consume the manual Your Expiration 2/minute allowance.
    window.__rwphLicenseMonitor = setInterval(checkLicenseNow, 10 * 60 * 1000);
  }

  function rwphFindAdminRoot(node) {
    return node?.closest?.("#rw-payout-helper") || document;
  }

  function rwphAdminQuery(root, selector) {
    return (root && root.querySelector ? root : document).querySelector(selector) || document.querySelector(selector);
  }

  function rwphAdminInputValue(root, selector) {
    return String(rwphAdminQuery(root, selector)?.value || "").trim();
  }

  function rwphRenderAdminStatusSummary(result) {
    const calculations = result.calculations || {};
    const cache = result.cache || {};
    const stats = result.stats || {};
    return `
      <div class="rw-admin-status-grid">
        <div class="rw-admin-status-card"><div class="rw-admin-status-label">Calculations</div><div class="rw-admin-status-value">${Number(calculations.active || 0)} active / direct start</div></div>
        <div class="rw-admin-status-card"><div class="rw-admin-status-label">Saved reports</div><div class="rw-admin-status-value">${Number(result.savedReports?.entries || 0)} stored</div></div>
        <div class="rw-admin-status-card"><div class="rw-admin-status-label">Reports loaded</div><div class="rw-admin-status-value">${Number(stats.savedReportsLoaded || 0)}</div></div>
        <div class="rw-admin-status-card"><div class="rw-admin-status-label">Reports made</div><div class="rw-admin-status-value">${Number(stats.reportsCreated || 0)}</div></div>
        <div class="rw-admin-status-card"><div class="rw-admin-status-label">Torn cache</div><div class="rw-admin-status-value">${Number(cache.tornMemoryEntries || 0)} live</div></div>
        <div class="rw-admin-status-card"><div class="rw-admin-status-label">Storage</div><div class="rw-admin-status-value">${esc(result.storage?.mode || "json")}</div></div>
      </div>`;
  }

  function rwphGetAdminKeyFromPanel(root) {
    const adminKey = rwphAdminInputValue(root, "#rw-admin-key");
    if (!adminKey) throw new Error("Enter your admin key first.");
    return adminKey;
  }

  async function rwphRefreshAdminLicensesFromPanel(root) {
    const status = rwphAdminQuery(root, "#rw-admin-status");
    const results = rwphAdminQuery(root, "#rw-admin-results");
    const adminKey = rwphGetAdminKeyFromPanel(root);
    GM_setValue(ADMIN_KEY_STORAGE_KEY, adminKey);
    if (status) status.textContent = "Loading licences from server...";
    if (results) results.innerHTML = "";
    const result = await adminRequest("POST", "/api/admin/licenses", adminKey);
    if (results) results.innerHTML = renderAdminLicenses(result.licenses || []);
    rwphToastPanelInfo(status, `Loaded ${(result.licenses || []).length} licence(s).`, "info", "RWPH Admin");
    return result;
  }

  async function rwphLoadAdminServerStatusFromPanel(root) {
    const status = rwphAdminQuery(root, "#rw-admin-status");
    const box = rwphAdminQuery(root, "#rw-admin-status-summary");
    const adminKey = rwphGetAdminKeyFromPanel(root);
    GM_setValue(ADMIN_KEY_STORAGE_KEY, adminKey);
    if (status) status.textContent = "Loading server status...";
    const result = await adminRequest("POST", "/api/admin/status", adminKey);
    if (box) box.innerHTML = rwphRenderAdminStatusSummary(result);
    rwphToastPanelInfo(status, `Server online. ${Number(result.calculations?.active || 0)} calculation(s) active. Saved Reports has ${Number(result.savedReports?.entries || 0)} stored report(s).`, "info", "RWPH Admin");
    return result;
  }

  function rwphFindAdminSection(root) {
    const scope = root && root.querySelector ? root : document;
    return scope.querySelector("#rw-paywall-admin-section, #rw-admin-tab-section") || document.querySelector("#rw-paywall-admin-section, #rw-admin-tab-section");
  }

  function rwphEnsureAdminGateNote(adminSection) {
    if (!adminSection) return null;
    let note = adminSection.querySelector("#rw-admin-gate-note");
    if (note) return note;
    note = document.createElement("div");
    note.id = "rw-admin-gate-note";
    note.className = "rw-muted rw-admin-gate-note";
    note.textContent = "Enter your ADMIN_KEY and click Save Admin Key to show the admin tools.";
    const saveBtn = adminSection.querySelector("#rw-admin-save-key");
    const row = saveBtn?.closest?.(".rw-actions") || adminSection.querySelector("#rw-admin-key")?.closest?.("label");
    if (row?.parentNode) row.insertAdjacentElement("afterend", note);
    else adminSection.prepend(note);
    return note;
  }

  function rwphSetAdminToolsVisible(root, visible, message = "") {
    const adminSection = rwphFindAdminSection(root);
    if (!adminSection) return;
    const unlocked = !!visible;
    adminSection.dataset.rwphAdminUnlocked = unlocked ? "1" : "0";

    const note = rwphEnsureAdminGateNote(adminSection);
    if (note) {
      note.hidden = unlocked;
      note.textContent = message || (unlocked
        ? "Admin tools unlocked."
        : "Enter your ADMIN_KEY and click Save Admin Key to show the admin tools.");
    }

    adminSection.querySelectorAll([
      "#rw-admin-list",
      "#rw-admin-status-load",
      "#rw-admin-default-setup",
      "#rw-move-launcher-admin",
      "#rw-admin-grant",
      "#rw-admin-extend",
      "#rw-admin-revoke",
      ".rw-admin-advanced-box",
      "#rw-admin-results"
    ].join(",")).forEach((el) => { el.hidden = !unlocked; });

    ["#rw-admin-torn-id", "#rw-admin-name", "#rw-admin-days"].forEach((selector) => {
      const label = adminSection.querySelector(selector)?.closest?.("label");
      if (label) label.hidden = !unlocked;
    });

    const status = adminSection.querySelector("#rw-admin-status");
    if (status && !unlocked && !String(status.textContent || "").trim()) {
      status.textContent = "Admin tools are hidden until a valid admin key is saved.";
    }
  }

  function rwphAdminToolsAreVisible(root) {
    return rwphFindAdminSection(root)?.dataset?.rwphAdminUnlocked === "1";
  }

  async function rwphSaveAdminKeyAndRevealTools(root, options = {}) {
    const status = rwphAdminQuery(root, "#rw-admin-status");
    const saveButton = rwphAdminQuery(root, "#rw-admin-save-key");
    const adminKey = rwphGetAdminKeyFromPanel(root);

    // Prevent impatient/double clicks from creating overlapping verification,
    // grant and licence-list requests.
    if (saveButton?.dataset?.rwphSaving === "1") return null;
    if (saveButton) {
      saveButton.dataset.rwphSaving = "1";
      saveButton.disabled = true;
      saveButton.dataset.rwphOriginalText = saveButton.dataset.rwphOriginalText || saveButton.textContent || "Save Admin Key";
      saveButton.textContent = "Checking...";
    }

    GM_setValue(ADMIN_KEY_STORAGE_KEY, adminKey);
    rwphSetAdminToolsVisible(root, false, "Checking admin key with the server...");
    if (status) status.textContent = "Checking admin key...";

    try {
      // v1.1.483: when owner auto-grant is enabled this ONE request both
      // verifies ADMIN_KEY and grants/refreshes the owner licence. The old
      // status -> grant-owner -> licences three-request chain was the delay.
      const result = options.grantOwner !== false
        ? await grantOwnerLicenseFromAdminKey(adminKey, null)
        : await adminRequest("POST", "/api/admin/status", adminKey);

      rwphSetAdminToolsVisible(root, true);

      const summary = rwphAdminQuery(root, "#rw-admin-status-summary");
      if (summary) {
        if (result?.calculations || result?.storage) summary.innerHTML = rwphRenderAdminStatusSummary(result);
        else summary.innerHTML = `<div class="rw-admin-status-grid"><div class="rw-admin-status-card"><div class="rw-admin-status-label">Admin</div><div class="rw-admin-status-value">Access unlocked</div></div><div class="rw-admin-status-card"><div class="rw-admin-status-label">Owner licence</div><div class="rw-admin-status-value">${esc(result?.expiresAt ? formatLicenseDaysLeft(result.expiresAt) : "Active")}</div></div></div>`;
      }

      if (result?.token) GM_setValue(PAYWALL_TOKEN_STORAGE_KEY, result.token);
      if (result?.expiresAt) rwphScheduleLicenseLockback(result.expiresAt);

      if (options.grantOwner !== false && result?.expiresAt) {
        rwphToastPanelInfo(status, `Admin access unlocked. Owner licence active for ${formatLicenseDaysLeft(result.expiresAt)}.`, "info", "RWPH Admin");
      } else {
        rwphToastPanelInfo(status, "Admin key verified. Admin tools unlocked.", "info", "RWPH Admin");
      }

      // Do not auto-load the full licence table here. It is intentionally a
      // separate List Licences action so Save Admin Key stays fast and stable.
      return result;
    } catch (e) {
      GM_setValue(ADMIN_KEY_STORAGE_KEY, "");
      rwphSetAdminToolsVisible(root, false, "Invalid admin key. Admin tools are still hidden.");
      throw e;
    } finally {
      if (saveButton) {
        saveButton.dataset.rwphSaving = "0";
        saveButton.disabled = false;
        saveButton.textContent = saveButton.dataset.rwphOriginalText || "Save Admin Key";
      }
    }
  }

  // BEGIN OPTIONAL ADMIN 100 MEMBER TEST TOOL (v1.1.555)
  // This entire block is intentionally self-contained. To remove this feature later,
  // delete this block and the single installer call at the top of rwphBindAdminControls().
  // It performs READ-ONLY Cached Reports list/open requests and never saves, replaces,
  // deletes, or mutates a real cached report.
  const RWPH_ADMIN_100_MEMBER_TEST_COUNT_V1555 = 100;

  function rwphCloneAdminTestValueV1555(value) {
    try { return JSON.parse(JSON.stringify(value ?? null)); }
    catch (_) { return value && typeof value === "object" ? { ...value } : value; }
  }

  function rwphBuildAdmin100MemberRowsV1555(sourceRows = []) {
    const payable = rwphRowsWithPositivePayout(Array.isArray(sourceRows) ? sourceRows : []);
    if (!payable.length) throw new Error("Cached Report 1 has no payable member rows to duplicate.");
    const rows = [];
    for (let index = 0; index < RWPH_ADMIN_100_MEMBER_TEST_COUNT_V1555; index += 1) {
      const source = payable[index % payable.length] || {};
      const clone = rwphCloneAdminTestValueV1555(source) || {};
      const sourceName = String(source.name || source.username || source.memberName || `Member ${index + 1}`).replace(/\s+/g, " ").trim();
      clone.id = `TEST-${String(index + 1).padStart(3, "0")}`;
      clone.name = `${sourceName} · Test ${String(index + 1).padStart(3, "0")}`;
      clone.rwphAdminTestMember = true;
      clone.rwphAdminTestIndex = index + 1;
      clone.rwphAdminTestSourceId = String(source.id || source.tornId || source.userId || "");
      rows.push(clone);
    }
    return rows;
  }

  function rwphBuildAdmin100MemberSummaryV1555(sourceSummary = {}, rows = [], sourceReport = {}) {
    const summary = rwphCloneAdminTestValueV1555(sourceSummary) || {};
    const pointsMode = !!(summary.pointsMode || summary.calculationMode === "points");
    const sum = (getter) => rows.reduce((total, row) => total + Number(getter(row) || 0), 0);
    const memberPayout = sum((row) => row.payout ?? row.payoutAmount ?? row.paymentAmount ?? row.memberPayment ?? row.amount);
    const totalWeight = sum((row) => row.weight);
    const totalPoints = sum((row) => row.points ?? row.weight);
    const totalWarHits = sum((row) => row.warHits ?? row.attacks);
    const totalRespect = sum((row) => row.totalRespect ?? row.respect);
    const totalPayableEvents = sum((row) => pointsMode ? row.payableEvents : (row.warHits ?? row.attacks));

    summary.memberPayout = memberPayout;
    summary.totalPayout = memberPayout;
    summary.totalPayoutDisplay = memberPayout;
    summary.overallTotalPayout = memberPayout;
    summary.totalWeight = totalWeight;
    summary.totalPoints = totalPoints;
    summary.totalWarHits = totalWarHits;
    summary.totalHits = totalWarHits;
    summary.totalAssists = sum((row) => row.assists);
    summary.totalOutsideHits = sum((row) => row.outsideHits);
    summary.totalRetaliationHits = sum((row) => row.retaliationHits);
    summary.totalEnemyFactionHospitalizingHits = sum((row) => row.enemyFactionHospitalizingHits);
    summary.totalEnemyFactionHospitalBonusPoints = sum((row) => row.enemyFactionHospitalBonusPoints);
    summary.totalFairFightBonusPoints = sum((row) => row.fairFightBonusPoints);
    summary.totalRespectBonusPoints = sum((row) => row.respectBonusPoints);
    summary.totalRespect = totalRespect;
    summary.totalPayableEvents = totalPayableEvents;
    summary.attacksFetched = sum((row) => row.totalTrackedHits || row.warHits || row.attacks || 0);
    summary.calcMeta = summary.calcMeta && typeof summary.calcMeta === "object" ? { ...summary.calcMeta } : {};
    summary.calcMeta.payableEvents = totalPayableEvents;
    summary.calcMeta.fairFightModifierSamples = sum((row) => row.fairFightSamples);
    summary.calcMeta.retaliationBonusPoints = sum((row) => row.retaliationBonusPoints);
    summary.calcMeta.overseasHits = sum((row) => row.overseasHits);
    summary.cachedReportLoaded = false;
    summary.cachedReportId = 0;
    summary.rwphAdminTest100 = true;
    summary.rwphAdminTestMemberCount = RWPH_ADMIN_100_MEMBER_TEST_COUNT_V1555;
    summary.rwphAdminTestSourceCacheId = Number(sourceReport?.cacheId || sourceReport?.id || 0);
    summary.rwphAdminTestSourceSavedAtMs = Number(sourceReport?.createdAtMs || sourceReport?.savedAtMs || 0);
    const warnings = Array.isArray(summary.warnings) ? [...summary.warnings] : [];
    warnings.unshift("ADMIN TEST ONLY — 100 synthetic duplicate members built from Cached Report 1. This test is not saved back to Cached Reports.");
    summary.warnings = warnings;
    return summary;
  }

  function rwphAdmin100MemberTestUserKeyV1555() {
    return String(
      document.getElementById("rw-key")?.value?.trim() ||
      document.getElementById("rw-paywall-key")?.value?.trim() ||
      GM_getValue(STORAGE_KEY, "") ||
      ""
    ).trim();
  }

  async function rwphRunAdmin100MemberTestV1555(rootScope, button) {
    const status = rwphAdminQuery(rootScope, "#rw-admin-status");
    const userKey = rwphAdmin100MemberTestUserKeyV1555();
    const token = GM_getValue(PAYWALL_TOKEN_STORAGE_KEY, "");
    if (!userKey) throw new Error("Save your Torn API key first so RWPH can identify the faction Cached Reports list.");

    const originalText = String(button?.textContent || "100 Member Test Calculation");
    if (button) {
      if (button.dataset.rwphRunning === "1") return;
      button.dataset.rwphRunning = "1";
      button.disabled = true;
      button.textContent = "Building 100 Member Test...";
    }

    try {
      rwphToastPanelInfo(status, "Reading Cached Report 1 for the 100-member admin test...", "info", "RWPH Admin Test");
      const listResult = await apiPost("/api/calc/cached-reports/list", rwphSavedReportsRequestBody(userKey, token, {
        databaseCheckNonce: `admin-test-${Date.now()}`,
      }));
      rwphRememberSavedReportsFactionId(listResult.factionId);
      const reports = Array.isArray(listResult.reports) ? listResult.reports : [];
      const firstReport = reports[0];
      const cacheId = Math.max(0, Math.floor(Number(firstReport?.cacheId || firstReport?.id || 0)));
      if (!firstReport || !cacheId) throw new Error("Cached Report 1 is empty. Save a completed report first, then run the test again.");

      const sourceResult = await apiPost("/api/calc/cached-reports/open", rwphSavedReportsRequestBody(userKey, token, { cacheId }));
      const testRows = rwphBuildAdmin100MemberRowsV1555(sourceResult.rows || []);
      const testSummary = rwphBuildAdmin100MemberSummaryV1555(sourceResult.summary || {}, testRows, firstReport);
      testSummary.factionName = sourceResult.factionName || testSummary.factionName || listResult.factionName || "Faction";
      testSummary.factionId = sourceResult.factionId || testSummary.factionId || listResult.factionId || "";
      testSummary.factionImageUrl = rwphFindFactionInfoImageUrl(testSummary.factionId || "") || rwphFullFactionImageUrlV1546(sourceResult.factionImageUrl || testSummary.factionImageUrl || "") || "";

      // Keep real Cached Reports untouched: only the normal Results globals are replaced in-memory.
      lastRows = testRows;
      lastSummary = testSummary;
      rwphUpdateLastResultsButton();
      const embeddedResults = document.getElementById("rw-results");
      if (embeddedResults) embeddedResults.innerHTML = renderRows(lastRows, lastSummary);

      const progressId = `rwph-admin-test100-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
      const resultsPanel = openBlankResultsTab(progressId);
      rwphSetResultsLoadingStepDone(resultsPanel, 0, 20, "Admin test authorised");
      rwphSetResultsLoadingStepDone(resultsPanel, 1, 45, "Cached Report 1 loaded");
      rwphSetResultsLoadingStepDone(resultsPanel, 2, 70, `Duplicated source members to ${RWPH_ADMIN_100_MEMBER_TEST_COUNT_V1555}`);
      rwphSetResultsLoadingStepDone(resultsPanel, 3, 90, "Test totals rebuilt in memory");
      const manualOpenReady = rwphPrepareManualResultsOpenButton(resultsPanel, progressId, lastRows, lastSummary);
      if (manualOpenReady) {
        rwphSetResultsLoadingStepDone(resultsPanel, 4, 100, "100-member admin test ready. Click Open Results.");
      } else {
        await rwphShowResultsLoadingCompletion(resultsPanel);
      }
      rwphToastPanelInfo(status, `100-member test ready from Cached Report 1. ${testRows.length} synthetic members were created in memory only.`, "info", "RWPH Admin Test");
    } finally {
      if (button) {
        button.dataset.rwphRunning = "0";
        button.disabled = false;
        button.textContent = originalText;
      }
    }
  }

  function rwphInstallOptionalAdmin100MemberTestV1555(root) {
    const scope = root && root.querySelector ? root : document;
    const adminSection = rwphFindAdminSection(scope);
    if (!adminSection || adminSection.querySelector("#rw-admin-test-100-members")) return;
    const adminBox = adminSection.querySelector(".rw-admin-unified-panel") || adminSection;
    let host = adminSection.querySelector(".rw-admin-advanced-box");
    if (!host) {
      host = document.createElement("div");
      host.className = "rw-admin-advanced-box";
      adminBox.appendChild(host);
    }

    const card = document.createElement("div");
    card.className = "rwph-admin-100-test-tool rw-small";
    card.style.cssText = "margin-top:8px;padding:8px;border:1px solid var(--rwph-theme-line);border-radius:9px;background:var(--rwph-theme-panel2);display:grid;gap:6px;";
    card.innerHTML = `
      <b style="color:var(--rwph-theme-text);">100 Member Test Calculation</b>
      <span>Reads <b>Cached Report 1</b>, duplicates its payable member rows to exactly <b>100 synthetic test members</b>, and opens the normal Results/Newsletter flow. The source cached report is never changed or replaced.</span>
      <button id="rw-admin-test-100-members" class="secondary" type="button">100 Member Test Calculation</button>`;
    host.appendChild(card);

    const button = card.querySelector("#rw-admin-test-100-members");
    button?.addEventListener("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();
      const rootScope = rwphFindAdminRoot(button);
      const status = rwphAdminQuery(rootScope, "#rw-admin-status");
      try {
        if (!rwphAdminToolsAreVisible(rootScope)) throw new Error("Save a valid admin key first. Admin tools are still locked.");
        await rwphRunAdmin100MemberTestV1555(rootScope, button);
      } catch (e) {
        rwphToastPanelError(status, `100-member test error: ${e.message || e}`, "RWPH Admin Test");
      }
    });
  }
  // END OPTIONAL ADMIN 100 MEMBER TEST TOOL (v1.1.555)

  function rwphBindAdminControls(root) {
    const panelRoot = root && root.addEventListener ? root : document;
    rwphInstallOptionalAdmin100MemberTestV1555(panelRoot);
    if (panelRoot.__rwphAdminDelegatedBound) return;
    panelRoot.__rwphAdminDelegatedBound = true;
    panelRoot.addEventListener("click", async (event) => {
      const target = event.target;
      const adminAction = target?.closest?.("#rw-admin-save-key, #rw-admin-list, #rw-admin-status-load, #rw-admin-default-setup, #rw-admin-grant, #rw-admin-extend, #rw-admin-revoke, .rw-admin-fill-revoke");
      if (!adminAction || !panelRoot.contains?.(adminAction)) return;
      const rootScope = rwphFindAdminRoot(adminAction);
      const status = rwphAdminQuery(rootScope, "#rw-admin-status");
      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation?.();
      try {
        if (adminAction.id !== "rw-admin-save-key" && !rwphAdminToolsAreVisible(rootScope)) {
          throw new Error("Save a valid admin key first. Admin tools are hidden until the server accepts the key.");
        }
        if (adminAction.classList?.contains("rw-admin-fill-revoke")) {
          const filledId = adminAction.dataset.tornId || "";
          const filledName = adminAction.dataset.name || (filledId ? `User ${filledId}` : "");
          const idInput = rwphAdminQuery(rootScope, "#rw-admin-torn-id");
          const nameInput = rwphAdminQuery(rootScope, "#rw-admin-name");
          if (idInput) idInput.value = filledId;
          if (nameInput) nameInput.value = filledName;
          rwphToastPanelInfo(status, filledName ? `Filled ${filledName} (${filledId}) into the admin form.` : `Filled Torn ID ${filledId} into the admin form.`, "info", "RWPH Admin");
          return;
        }

        if (adminAction.id === "rw-admin-status-load") {
          await rwphLoadAdminServerStatusFromPanel(rootScope);
          return;
        }

        if (adminAction.id === "rw-admin-default-setup") {
          const adminKey = rwphGetAdminKeyFromPanel(rootScope);
          GM_setValue(ADMIN_KEY_STORAGE_KEY, adminKey);
          rwphOpenDefaultSetupPanel(adminKey);
          return;
        }

        if (adminAction.id === "rw-admin-list") {
          await rwphRefreshAdminLicensesFromPanel(rootScope);
          return;
        }

        if (adminAction.id === "rw-admin-save-key") {
          await rwphSaveAdminKeyAndRevealTools(rootScope, { grantOwner: true, refreshLicenses: false });
          return;
        }

        if (adminAction.id === "rw-admin-grant") {
          const adminKey = rwphGetAdminKeyFromPanel(rootScope);
          const tornId = rwphAdminInputValue(rootScope, "#rw-admin-torn-id");
          const name = rwphAdminInputValue(rootScope, "#rw-admin-name") || `User ${tornId}`;
          const days = Number(rwphAdminQuery(rootScope, "#rw-admin-days")?.value || 30);
          if (!tornId) return alert("Enter the player's Torn ID.");
          if (!days || days <= 0) return alert("Enter valid licence days.");
          GM_setValue(ADMIN_KEY_STORAGE_KEY, adminKey);
          if (status) status.textContent = `Granting ${days} day licence to ${name} (${tornId})...`;
          const result = await adminRequest("POST", "/api/admin/grant", adminKey, { tornId, name, days });
          rwphToastPanelInfo(status, `Granted licence to ${result.name || name} (${result.tornId || tornId}) until ${formatUnixDate(result.expiresAt)}.`, "info", "RWPH Admin");
          await rwphRefreshAdminLicensesFromPanel(rootScope);
          return;
        }

        if (adminAction.id === "rw-admin-extend") {
          const result = await extendAdminLicenseFromCurrentForm(status);
          if (result) await rwphRefreshAdminLicensesFromPanel(rootScope);
          return;
        }

        if (adminAction.id === "rw-admin-revoke") {
          const result = await removeAdminLicenseDaysFromCurrentForm(status);
          if (result) await rwphRefreshAdminLicensesFromPanel(rootScope);
        }
      } catch (e) {
        const actionName = adminAction.id === "rw-admin-save-key" ? "Admin key save" : adminAction.id === "rw-admin-list" ? "Admin list" : adminAction.id === "rw-admin-status-load" ? "Server status" : adminAction.id === "rw-admin-default-setup" ? "Default setup" : adminAction.id === "rw-admin-grant" ? "Admin grant" : adminAction.id === "rw-admin-extend" ? "Admin extend" : adminAction.id === "rw-admin-revoke" ? "Admin remove" : "Admin action";
        rwphToastPanelError(status, `${actionName} error: ${e.message}`, "RWPH Admin");
      }
    }, true);
  }
  async function rwphCheckLicenseOnPanelOpen() {
    const info = await getSavedLicenseInfo();

    if (!info.valid) {
      // Preserve a saved token during temporary connectivity problems, so the next check can recover.
      if (!info.transient) GM_setValue(PAYWALL_TOKEN_STORAGE_KEY, "");
      if (info.transient) return { valid: false, transient: true, info, message: "Licence server temporarily unavailable. Your saved licence was not cleared. Reopen the panel to retry. " + (info.error || "") };
      const lowerError = String(info.error || "").toLowerCase();
      const message = info.revoked
        ? "Your licence was revoked by an admin. Buy Licence or contact the owner to unlock RWPH again."
        : lowerError.includes("expired")
          ? "Your licence has expired. Buy Licence or extend your licence to unlock RWPH again."
          : lowerError.includes("server licence") || lowerError.includes("server license") || lowerError.includes("no active")
            ? "No active server licence was found. Buy Licence, Extend Licence, or ask an admin to grant licence days."
            : (info.error || "No active licence found. Buy Licence, Extend Licence, or use Unlock Panel after your licence is active.");
      return { valid: false, info, message };
    }

    if (info.token) GM_setValue(PAYWALL_TOKEN_STORAGE_KEY, info.token);
    if (info.expiresAt) rwphScheduleLicenseLockback(info.expiresAt);
    return { valid: true, info, message: "Licence active." };
  }

  async function rwphUnlockMainPanelIfActive(statusEl, reason = "auto") {
    const panel = document.getElementById("rw-payout-helper");
    const keyInput = document.getElementById("rw-paywall-key");
    if (!panel || !keyInput || document.getElementById("rw-key")) return false;
    if (window.__rwphAutoUnlockInFlight) return false;

    const key = keyInput.value.trim();
    const token = GM_getValue(PAYWALL_TOKEN_STORAGE_KEY, "");
    if (!key && !token) return false;

    window.__rwphAutoUnlockInFlight = true;
    try {
      if (key) GM_setValue(STORAGE_KEY, key);
      if (statusEl) {
        statusEl.textContent = reason === "save"
          ? "API key saved. Checking active licence..."
          : "Checking active licence...";
      }

      const info = await getSavedLicenseInfo();
      if (!panel.isConnected || document.getElementById("rw-key")) return false;

      if (!info.valid) {
        if (statusEl && reason !== "silent") {
          statusEl.textContent = "No active licence found yet. Buy Licence, Extend Licence, or use Unlock Panel after payment is complete.";
        }
        return false;
      }

      if (info.token) GM_setValue(PAYWALL_TOKEN_STORAGE_KEY, info.token);
      if (info.expiresAt) rwphScheduleLicenseLockback(info.expiresAt);
      clearPendingPayment();
      showMainScreen(panel);

      const mainStatus = document.getElementById("rw-status");
      if (mainStatus) {
        mainStatus.textContent = `Licence active for ${info.name || "this user"}. Main panel unlocked automatically.`;
      }
      return true;
    } catch (e) {
      if (statusEl && reason !== "silent") statusEl.textContent = "Auto-unlock check failed: " + (e.message || e);
      return false;
    } finally {
      window.__rwphAutoUnlockInFlight = false;
    }
  }

